import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`tiktok-shop-launch`,heroTitle:`Launch your TikTok Shop in minutes`,heroSubtitle:`Perplexity Computer identifies your top products with TikTok Shop viral potential based on trending hashtags, competitor sales, and price point analysis, then delivers optimized listings, video script hooks, and an influencer outreach template.`,inputUrlCta:`Launch my TikTok Shop`,inputUrlPlaceholder:`e.g. https://yourshopify.com`,inputUrlPrefill:`Go to {url} and analyze the product catalog to identify products with the highest TikTok Shop viral potential. (1) Scrape the full product catalog — extracting names, prices, categories, and images. (2) Research trending TikTok hashtags and sounds in each product category — identify which trends are still growing vs peaking. (3) Analyze competitor TikTok Shop listings in each category — studying their pricing, video styles, and estimated sales volume. (4) Score each product on viral potential based on price point (impulse buy range), visual appeal, demo-ability, trend alignment, and margin headroom. (5) For the top 10 products, write optimized TikTok Shop listings with SEO-friendly titles, benefit-led descriptions, and keyword tags. (6) Write 3 video script hooks per product — attention-grabbing opening lines designed for the first 3 seconds of a TikTok. (7) Create an influencer outreach template with personalized pitch angles for micro-influencers in each product category. (8) Deliver a complete launch plan with product rankings, optimized listings, video hooks, and outreach templates.`,heroOverlaySteps:[`Analyzing your catalog and scoring products for TikTok viral potential`,`Researching trending hashtags, competitor sales, and price points`,`Writing optimized listings, video script hooks, and outreach templates`,`Complete TikTok Shop launch plan with rankings and assets — ready to go`],generatingSteps:[`Visiting {url} to scrape your product catalog and analyze each item`,`Designing an agent to research TikTok trends, competitor sales, and viral signals`,`Configuring listing optimization and video script hook generation`,`Setting up deliverable with product rankings, listings, hooks, and outreach templates`],featureSectionTitle:`From store to TikTok Shop`,featureCardTitles:[`Connects to your e-commerce stack`,`Outputs you can launch with`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Shopify, Amazon, TikTok, Google Sheets — Computer plugs into your tools so product data, listings, and launch assets flow into one workflow.`,`Optimized listings. Video script hooks. Influencer outreach templates. Product rankings. Computer delivers everything you need to launch and sell on TikTok Shop.`],capabilitySectionTitle:`Your TikTok commerce strategist, on autopilot`,capabilitySectionSubtitle:`Paste your store URL, step away, come back to a complete TikTok Shop launch plan.`,capabilityCards:[{title:`Product Selection`,description:`Computer can score every product in your catalog on viral potential — analyzing price point, visual appeal, demo-ability, trend alignment, and margin headroom.`},{title:`Trend Analysis`,description:`Computer can research trending TikTok hashtags, sounds, and video formats in your categories — identifying which trends are still growing vs peaking.`},{title:`Video Script Hooks`,description:`Computer can write attention-grabbing opening lines designed for the first 3 seconds of a TikTok — optimized for scroll-stopping engagement.`},{title:`Connect Your Tools`,description:`Computer can read from Shopify, Amazon, TikTok, Google Sheets, and more — build workflows across your entire e-commerce and social stack.`},{title:`Remember & Learn`,description:`Computer can remember your best sellers, past video performance, and audience demographics across sessions — so every launch builds on what works.`},{title:`Influencer Outreach`,description:`Computer can identify micro-influencers in your product categories and create personalized pitch templates — ready to send for affiliate partnerships.`}]});export{t as default};
